// Generated by Cypress Author — 2025-07-15
// POC E2E test for the kaoto-web package — About modal open / verify / close.
//
// Run only these tests:
//   yarn workspace @kaoto/kaoto-tests e2e:kaoto-web --config baseUrl=http://localhost:5174
//
// Or headless:
//   yarn workspace @kaoto/kaoto-tests e2e:kaoto-web:headless --config baseUrl=http://localhost:5174

// ---------------------------------------------------------------------------
// Carbon DOM notes (verified against @carbon/react source):
//
// MenuButton:
//   - `data-testid` lands on the wrapper <div>, NOT the inner <button>.
//   - Must click the inner <button> (labelled "Menu") to fire the toggle.
//   - The dropdown <ul role="menu"> is portalled to document.body via
//     createPortal, so cy.contains('[role="menuitem"]', …) finds it at root.
//
// MenuItem:
//   - Renders as <div role="menuitem">. Text comes from the `label` prop.
//   - No data-testid on individual items; text + role is the stable selector.
//
// Modal (passiveModal):
//   - NOT portalled — renders inline in the component tree.
//   - KaotoAboutModal returns null when closed → use .should('not.exist').
//   - Close button: <button aria-label="Close"> inside the modal container.
// ---------------------------------------------------------------------------

describe('kaoto-web: About modal', { tags: ['kaoto-web'] }, () => {
  beforeEach(() => {
    // The AppMenuDropdown (with "About") lives inside ProjectToolbar, which is
    // only rendered on project pages (/projects/:projectId).
    cy.visit('/projects/project50');
  });

  // Helper: open the Carbon MenuButton and click the "About" menu item.
  // Extracted here because every test needs this two-step preamble.
  const openAboutModal = () => {
    // Click the inner <button> inside the MenuButton wrapper div.
    cy.contains('button', 'Menu').click();
    // The menu list is portalled to document.body — cy.contains searches the
    // full document so it finds the item even outside the component subtree.
    cy.contains('[role="menuitem"]', 'About').click();
  };

  it('Menu button opens → About menu item triggers → modal is visible', () => {
    openAboutModal();

    cy.get('[data-testid="kaoto-about-modal"]').should('be.visible');
    cy.get('[data-testid="kaoto-about-modal"]').contains('About Kaoto').should('be.visible');
  });

  it('About modal contains the expected version information rows', () => {
    openAboutModal();

    cy.get('[data-testid="kaoto-about-modal"]').should('be.visible');

    // Version row — value should be a non-empty string
    cy.get('[data-testid="about-version"]').should('exist').and('not.be.empty');

    // Git commit hash row
    cy.get('[data-testid="about-git-commit-hash"]').should('exist');

    // Git last commit date row
    cy.get('[data-testid="about-git-last-commit-date"]').should('exist');
  });

  it('close button dismisses the modal → modal is removed from DOM', () => {
    openAboutModal();

    cy.get('[data-testid="kaoto-about-modal"]').should('be.visible');

    // Carbon passiveModal renders a single <button aria-label="Close"> inside
    // the modal container. KaotoAboutModal returns null on close, so the whole
    // element is unmounted — assert 'not.exist', not just 'not.be.visible'.
    cy.get('[data-testid="kaoto-about-modal"]').within(() => {
      cy.get('button[aria-label="Close"]').click();
    });

    cy.get('[data-testid="kaoto-about-modal"]').should('not.exist');
  });
});
